                }
            }
            _ => {
                eprintln!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS]\n\nFor more information, try '--help'.", arg);
                exit(2);
            }
        }
        i += 1;
    }

    args
}

fn parse_toml_config(config_path: &Path) -> Result<Config, ()> {
    let content = match fs::read_to_string(config_path) {
        Ok(c) => c,
        Err(_) => return Err(()),
    };

    let mut cfg = Config::default();

    // Simple TOML parser for clog configuration
    let mut current_section = "";
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') && line.ends_with(']') {
            current_section = &line[1..line.len() - 1];
            continue;
        }

        if current_section == "clog" {
            if let Some((k, v)) = line.split_once('=') {
                let k = k.trim();
                let v = v.trim().trim_matches('"').trim_matches('\'');
                match k {
                    "repository" => cfg.repository = Some(v.to_string()),
                    "subtitle" => cfg.subtitle = Some(v.to_string()),
                    "from-latest-tag" | "from_latest_tag" => cfg.from_latest_tag = v == "true",
                    "link-style" | "link_style" => {
                        let ls = match v {
                            "gitlab" => LinkStyle::Gitlab,
                            "stash" => LinkStyle::Stash,
                            "cgit" => LinkStyle::Cgit,
                            _ => LinkStyle::Github,
                        };
                        cfg.link_style = Some(ls);
                    }
                    _ => {}
                }
            }
        } else if current_section == "sections" {
            if let Some((k, v)) = line.split_once('=') {
                let k = k.trim().trim_matches('"').trim_matches('\'');
                let v = v.trim();
                if v.starts_with('[') && v.ends_with(']') {
                    let items: Vec<String> = v[1..v.len() - 1]
                        .split(',')
                        .map(|s| s.trim().trim_matches('"').trim_matches('\'').to_string())
                        .filter(|s| !s.is_empty())
                        .collect();
                    if cfg.sections.is_none() {
                        cfg.sections = Some(BTreeMap::new());
                    }
                    cfg.sections.as_mut().unwrap().insert(k.to_string(), items);
                } else {
                    return Err(());
                }
            }
        } else if current_section == "aliases" {
            if let Some((k, v)) = line.split_once('=') {
                let k = k.trim().trim_matches('"').trim_matches('\'');
                let v = v.trim().trim_matches('"').trim_matches('\'');
                if cfg.aliases.is_none() {
                    cfg.aliases = Some(HashMap::new());
                }
                cfg.aliases.as_mut().unwrap().insert(k.to_string(), v.to_string());
            }
        }
    }

    Ok(cfg)
}

fn get_default_sections() -> BTreeMap<String, Vec<String>> {
    let mut map = BTreeMap::new();
    map.insert("Features".to_string(), vec!["feat".to_string(), "ft".to_string()]);
    map.insert("Bug Fixes".to_string(), vec!["fix".to_string(), "fx".to_string()]);
    map.insert("Documentation".to_string(), vec!["docs".to_string()]);
    map.insert("Style Fixes".to_string(), vec!["style".to_string()]);
    map.insert("Refactoring".to_string(), vec!["refactor".to_string()]);
    map.insert("Performance Improvements".to_string(), vec!["perf".to_string()]);
    map.insert("Tests".to_string(), vec!["test".to_string()]);
    map.insert("Chores".to_string(), vec!["chore".to_string()]);
    map
}

fn make_commit_link(repository: Option<&str>, link_style: &LinkStyle, hash: &str, hash8: &str) -> String {
    match repository {
        Some(repo) => match link_style {
            LinkStyle::Github | LinkStyle::Gitlab => format!("{}/commit/{}", repo, hash),
            LinkStyle::Stash => format!("{}/commits/{}", repo, hash),
            LinkStyle::Cgit => format!("{}/commit/?id={}", repo, hash),
        },
        None => hash8.to_string(),
    }
}

fn make_issue_link(repository: Option<&str>, link_style: &LinkStyle, issue: u64) -> String {
    match repository {
        Some(repo) => match link_style {
            LinkStyle::Github | LinkStyle::Gitlab => format!("{}/issues/{}", repo, issue),
            LinkStyle::Stash | LinkStyle::Cgit => issue.to_string(),
        },
        None => issue.to_string(),
    }
}

fn parse_issues(text: &str, repository: Option<&str>, link_style: &LinkStyle) -> Vec<Issue> {
    let mut issues = Vec::new();
    // Look for Closes, Fixes, Resolves followed by #number or comma separated #numbers
    for line in text.lines() {
        let trimmed = line.trim();
        let prefixes = ["Closes", "Fixes", "Resolves"];
        for prefix in &prefixes {
            if let Some(rest) = trimmed.strip_prefix(prefix) {
                // rest might contain #101, #102 or 101, 102
                for part in rest.split(',') {
                    let token = part.trim().trim_start_matches('#');
                    let num_str: String = token.chars().take_while(|c| c.is_ascii_digit()).collect();
                    if let Ok(num) = num_str.parse::<u64>() {
                        let link = make_issue_link(repository, link_style, num);
                        issues.push(Issue {
                            issue: num,
                            issue_link: link,
                        });
                    }
                }
            }
        }
    }
    issues
}

fn main() {
    let start_time = Instant::now();
    let cli_args = parse_cli_args();

    // Config path resolution
    let default_config_path = PathBuf::from(".clog.toml");
    let (config_path, is_explicit_config) = if let Some(ref c) = cli_args.config {
        (c.clone(), true)
    } else {
        (default_config_path, false)
    };

    let config_res = parse_toml_config(&config_path);
    let cfg = match config_res {
        Ok(c) => c,
        Err(_) => {
            if is_explicit_config || config_path.exists() {
                // If file exists but TOML invalid:
                if config_path.exists() {
                    let content = fs::read_to_string(&config_path).unwrap_or_default();
                    if !content.trim().is_empty() {
                        eprintln!("\x1b[1;31merror:\x1b[0m Failed to parse TOML configuration file");
                        exit(1);
                    }
                }
                eprintln!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file");
                exit(1);
            } else {
                eprintln!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file");
                exit(1);
            }
        }
    };

    let repository = cli_args.repository.or(cfg.repository);
    let subtitle = cli_args.subtitle.or(cfg.subtitle);
    let from_latest_tag = cli_args.from_latest_tag || cfg.from_latest_tag;
    let link_style = cli_args.link_style.or(cfg.link_style).unwrap_or(LinkStyle::Github);
    let format = cli_args.format.unwrap_or(OutputFormat::Markdown);
    let sections_map = cfg.sections.unwrap_or_else(get_default_sections);
    let aliases_map = cfg.aliases.unwrap_or_default();

    // Determine version
    let mut version = cli_args.setversion;

    if cli_args.major || cli_args.minor || cli_args.patch {
        if version.is_none() {
            eprintln!("\x1b[1;31merror:\x1b[0m Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.");
            exit(1);
        }
    }

    // Git directory / work tree resolution
    let work_tree = cli_args.work_tree.unwrap_or_else(|| PathBuf::from("."));
    let git_dir = cli_args.git_dir.unwrap_or_else(|| work_tree.join(".git"));

    // Determine 'from' commit
    let from_commit = if from_latest_tag {
        // Run git describe --tags --abbrev=0
        let output = Command::new("git")
            .arg("--git-dir")
            .arg(&git_dir)
            .arg("--work-tree")
            .arg(&work_tree)
            .args(["describe", "--tags", "--abbrev=0"])
            .output();
        if let Ok(out) = output {
            if out.status.success() {
                let tag = String::from_utf8_lossy(&out.stdout).trim().to_string();
                if !tag.is_empty() {
                    Some(tag)
                } else {
                    None
                }
            } else {
                None
            }
        } else {
            None
        }
    } else {
        cli_args.from
    };

    let to_commit = cli_args.to.unwrap_or_else(|| "HEAD".to_string());

    // Fetch commit history
    let range = match from_commit {
        Some(ref f) => format!("{}..{}", f, to_commit),
        None => to_commit.clone(),
    };

    let git_output = Command::new("git")
        .arg("--git-dir")
        .arg(&git_dir)
        .arg("--work-tree")
        .arg(&work_tree)
        .args(["log", &range, "--format=%H%n%B%n==END_COMMIT=="])
        .output();

    let mut raw_commits = Vec::new();
    if let Ok(out) = git_output {
        if out.status.success() {
            let text = String::from_utf8_lossy(&out.stdout);
            for block in text.split("==END_COMMIT==") {
                let block = block.trim();
                if block.is_empty() {
                    continue;
                }
                let mut lines = block.lines();
                if let Some(hash) = lines.next() {
                    let hash = hash.trim();
                    if hash.len() >= 8 {
                        let hash8 = hash[..8].to_string();
                        let body: Vec<&str> = lines.collect();
                        raw_commits.push((hash.to_string(), hash8, body.join("\n")));
                    }
                }
            }
        }
    }

    // Process commits
    let mut parsed_commits = Vec::new();

    for (hash, hash8, full_msg) in raw_commits {
        let msg_trimmed = full_msg.trim();
        if msg_trimmed.is_empty() {
            continue;
        }

        let first_line = msg_trimmed.lines().next().unwrap_or("").trim();

        // Parse type(scope): subject or type: subject
        let mut commit_type = String::new();
        let mut component = None;
        let mut subject = String::new();

        if let Some(colon_idx) = first_line.find(':') {
            let prefix = &first_line[..colon_idx];
            let raw_subject = &first_line[colon_idx + 1..];

            // Check if prefix ends with !
            let prefix_clean = if prefix.ends_with('!') {
                &prefix[..prefix.len() - 1]
            } else {
                prefix
            };

            if let Some(open_paren) = prefix_clean.find('(') {
                if prefix_clean.ends_with(')') {
                    commit_type = prefix_clean[..open_paren].to_string();
                    component = Some(prefix_clean[open_paren + 1..prefix_clean.len() - 1].to_string());
                } else {
                    commit_type = prefix_clean.to_string();
                }
            } else {
                commit_type = prefix_clean.to_string();
            }

            subject = raw_subject.to_string();
        }

        // Apply aliases
        if let Some(target_type) = aliases_map.get(&commit_type) {
            commit_type = target_type.clone();
        }

        let commit_link = make_commit_link(repository.as_deref(), &link_style, &hash, &hash8);
        let closes = parse_issues(msg_trimmed, repository.as_deref(), &link_style);

        let has_bc = msg_trimmed.contains("BREAKING CHANGE:") || msg_trimmed.contains("BREAKING CHANGES:");
        let breaks = if has_bc { closes.clone() } else { Vec::new() };

        if !commit_type.is_empty() {
            parsed_commits.push(Commit {
                hash,
                hash8,
                commit_type,
                component,
                subject,
                commit_link,
                closes,
                breaks,
                has_breaking_change: has_bc,
            });
        }
    }

    // Group commits into sections
    // sections_map: Section Title -> Vec<commit_types>
    let mut sections: Vec<(String, Vec<Commit>)> = Vec::new();

    for (sec_title, types) in &sections_map {
        let mut sec_commits = Vec::new();
        for c in &parsed_commits {
            let mut matches = false;
            for t in types {
                if t == "breaking" && c.has_breaking_change {
                    matches = true;
                    break;
                } else if &c.commit_type == t {
                    matches = true;
                    break;
                }
            }
            if matches {
                sec_commits.push(c.clone());
            }
        }

        if !sec_commits.is_empty() {
            sections.push((sec_title.clone(), sec_commits));
        }
    }

    // Today's date YYYY-MM-DD
    let date = match Command::new("date").args(["+%" + "Y-%m-%d"]).output() {
        Ok(out) => String::from_utf8_lossy(&out.stdout).trim().to_string(),
        Err(_) => "2026-07-31".to_string(),
    };

    // Generate output string
    let output_str = match format {
        OutputFormat::Markdown => {
            let mut out = String::new();
            let ver_str = version.as_deref().unwrap_or("");
            out.push_str(&format!("<a name=\"{}\"></a>\n", ver_str));

            let sub_str = subtitle.as_deref().unwrap_or("");
            if sub_str.is_empty() {
                out.push_str(&format!("## {}  ({})\n", ver_str, date));
            } else {
                out.push_str(&format!("## {} {} ({})\n", ver_str, sub_str, date));
            }

            for (sec_title, sec_commits) in &sections {
                out.push_str(&format!("\n\n#### {}\n\n", sec_title));

                // Separate unscoped and scoped
                let mut unscoped = Vec::new();
                let mut scoped: BTreeMap<String, Vec<&Commit>> = BTreeMap::new();

                for c in sec_commits {
                    match c.component {
                        Some(ref comp) => {
                            scoped.entry(comp.clone()).or_default().push(c);
                        }
                        None => unscoped.push(c),
                    }
                }

                // Unscoped first
                for c in unscoped {
                    let closes_str = if c.closes.is_empty() {
                        String::new()
                    } else {
                        let issue_links: Vec<String> = c
                            .closes
                            .iter()
                            .map(|i| {
                                if i.issue_link == i.issue.to_string() {
                                    format!("[#{}]({})", i.issue, i.issue_link)
                                } else {
                                    format!("[#{}]({})", i.issue, i.issue_link)
                                }
                            })
                            .collect();
                        format!(", closes {}", issue_links.join(", "))
                    };

                    out.push_str(&format!(
                        "*  {} ([{}]({}){})\n",
                        c.subject, c.hash8, c.commit_link, closes_str
                    ));
                }

                // Scoped sorted by scope name
                for (comp, commits) in scoped {
                    if commits.len() == 1 {
                        let c = commits[0];
                        let closes_str = if c.closes.is_empty() {
                            String::new()
                        } else {
                            let issue_links: Vec<String> = c
                                .closes
                                .iter()
                                .map(|i| format!("[#{}]({})", i.issue, i.issue_link))
                                .collect();
                            format!(", closes {}", issue_links.join(", "))
                        };
                        out.push_str(&format!(
                            "* **{}:** {} ([{}]({}){})\n",
                            comp, c.subject, c.hash8, c.commit_link, closes_str
                        ));
                    } else {
                        out.push_str(&format!("* **{}:**\n", comp));
                        for c in commits {
                            let closes_str = if c.closes.is_empty() {
                                String::new()
                            } else {
                                let issue_links: Vec<String> = c
                                    .closes
                                    .iter()
                                    .map(|i| format!("[#{}]({})", i.issue, i.issue_link))
                                    .collect();
                                format!(", closes {}", issue_links.join(", "))
                            };
                            out.push_str(&format!(
                                "  * {} ([{}]({}){})\n",
                                c.subject, c.hash8, c.commit_link, closes_str
                            ));
                        }
                    }
                }
            }

            out
        }
        OutputFormat::Json => {
            let mut out = String::new();
            out.push_str("{\"header\":{\"version\":");
            match version {
                Some(ref v) => out.push_str(&format!("Some(\"{}\")", v)),
                None => out.push_str("None"),
            }
            out.push_str(",\"patch_version\":false,\"subtitle\":");
            match subtitle {
                Some(ref s) => out.push_str(&format!("Some(\"{}\")", s)),
                None => out.push_str("null"),
            }
            out.push_str(&format!(",\"date\":\"{}\"}},\"sections\":[", date));

            let mut sec_jsons = Vec::new();
            for (sec_title, sec_commits) in &sections {
                let mut sec_str = format!("{{\"title\":\"{}\",\"commits\":[", sec_title);
                let mut commit_jsons = Vec::new();

                for c in sec_commits {
                    let mut c_str = String::new();
                    c_str.push_str("{\"component\":");
                    match c.component {
                        Some(ref comp) => c_str.push_str(&format!("\"{}\"", comp)),
                        None => c_str.push_str("null"),
                    }
                    // Subject string escaping
                    let escaped_subject = c.subject.replace('\\', "\\\\").replace('"', "\\\"");
                    c_str.push_str(&format!(",\"subject\":\"{}\",\"commit_link\":\"{}\",\"closes\":", escaped_subject, c.commit_link));

                    if c.closes.is_empty() {
                        c_str.push_str("null");
                    } else {
                        let issue_objs: Vec<String> = c
                            .closes
                            .iter()
                            .map(|i| format!("{{\"issue\":{},\"issue_link\":\"{}\"}}", i.issue, i.issue_link))
                            .collect();
                        c_str.push_str(&format!("[{}]", issue_objs.join(",")));
                    }

                    c_str.push_str(",\"breaks\":");
                    if c.has_breaking_change {
                        let issue_objs: Vec<String> = c
                            .breaks
                            .iter()
                            .map(|i| format!("{{\"issue\":{},\"issue_link\":\"{}\"}}", i.issue, i.issue_link))
                            .collect();
                        c_str.push_str(&format!("[{}]", issue_objs.join(",")));
                    } else {
                        c_str.push_str("null");
                    }

                    c_str.push('}');
                    commit_jsons.push(c_str);
                }

                sec_str.push_str(&commit_jsons.join(","));
                sec_str.push_str("]}");
                sec_jsons.push(sec_str);
            }

            out.push_str(&sec_jsons.join(","));
            out.push_str("]}");
            out
        }
    };

    let duration_ms = start_time.elapsed().as_millis();

    // Determine output destination
    // Handle -C, -o, -i
    if let Some(ref changelog_path) = cli_args.changelog {
        let old_content = fs::read_to_string(changelog_path).unwrap_or_default();
        let final_content = if old_content.is_empty() {
            format!("{}\n\n\n\n", output_str)
        } else {
            format!("{}\n\n\n\n{}", output_str, old_content)
        };
        let _ = fs::write(changelog_path, final_content);
        println!("changelog written. (took {} ms)", duration_ms);
    } else if let Some(ref outfile_path) = cli_args.outfile {
        let old_content = if let Some(ref infile_path) = cli_args.infile {
            fs::read_to_string(infile_path).unwrap_or_default()
        } else {
            String::new()
        };
        let final_content = if old_content.is_empty() {
            format!("{}\n\n\n\n", output_str)
        } else {
            format!("{}\n\n\n\n{}", output_str, old_content)
        };
        let _ = fs::write(outfile_path, final_content);
        println!("changelog written. (took {} ms)", duration_ms);
    } else {
        print!("{}", output_str);
        println!("changelog written. (took {} ms)", duration_ms);
    }
}
EOF"}

{"command":"cat <<'EOF' > src/main.rs
use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{exit, Command};
use std::time::Instant;

#[derive(Debug, Clone, PartialEq)]
enum OutputFormat {
    Markdown,
    Json,
}

#[derive(Debug, Clone, PartialEq)]
enum LinkStyle {
    Github,
    Gitlab,
    Stash,
    Cgit,
}

#[derive(Debug, Default, Clone)]
struct Args {
    repository: Option<String>,
    from: Option<String>,
    to: Option<String>,
    format: Option<OutputFormat>,
    major: bool,
    minor: bool,
    patch: bool,
    git_dir: Option<PathBuf>,
    work_tree: Option<PathBuf>,
    subtitle: Option<String>,
    outfile: Option<PathBuf>,
    config: Option<PathBuf>,
    infile: Option<PathBuf>,
    setversion: Option<String>,
    from_latest_tag: bool,
    link_style: Option<LinkStyle>,
    changelog: Option<PathBuf>,
}

#[derive(Debug, Default, Clone)]
struct Config {
    repository: Option<String>,
    subtitle: Option<String>,
    from_latest_tag: bool,
    link_style: Option<LinkStyle>,
    sections: Option<Vec<(String, Vec<String>)>>,
    aliases: Option<HashMap<String, String>>,
}

#[derive(Debug, Clone)]
struct Issue {
    issue: u64,
    issue_link: String,
}

#[derive(Debug, Clone)]
struct Commit {
    hash: String,
    hash8: String,
    commit_type: String,
    component: Option<String>,
    subject: String,
    commit_link: String,
    closes: Vec<Issue>,
    breaks: Vec<Issue>,
    has_breaking_change: bool,
}

fn print_help() {
    print!(
r#"a conventional changelog for the rest of us

Usage: executable [OPTIONS]

Options:
  -r, --repository <URL>  Repository used for generating commit and issue links (without the .git,
                          e.g. https://github.com/thoughtram/clog)
  -f, --from <COMMIT>     e.g. 12a8546
  -T, --format <STR>      The output format, defaults to markdown [default: markdown] [possible
                          values: markdown, json]
  -M, --major             Increment major version by one (Sets minor and patch to 0)
  -g, --git-dir <PATH>    Local .git directory (defaults to "$(pwd)/.git")
  -w, --work-tree <PATH>  Local working tree of the git project (defaults to "$(pwd)")
  -m, --minor             Increment minor version by one (Sets patch to 0)
  -p, --patch             Increment patch version by one
  -s, --subtitle <STR>    
  -t, --to <COMMIT>       e.g. 8057684 [default: HEAD]
  -o, --outfile <PATH>    Where to write the changelog (Defaults to stdout when omitted)
  -c, --config <COMMIT>   The Clog Configuration TOML file to use [default: .clog.toml]
  -i, --infile <PATH>     A changelog to append to, but *NOT* write to (Useful in conjunction with
                          --outfile)
      --setversion <VER>  e.g. 1.0.1
  -F, --from-latest-tag   use latest tag as start (instead of --from)
  -l, --link-style <STR>  The style of repository link to generate [default: github] [possible
                          values: github, gitlab, stash, cgit]
  -C, --changelog <PATH>  A previous changelog to prepend new changes to (this is like using the
                          same file for both --infile and --outfile and should not be used in
                          conjunction with either)
  -h, --help              Print help
  -V, --version           Print version


If your .git directory is a child of your project directory (most common, such as /myproject/.git)
AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only
need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you
don't need to use both.

If using the --config to specify a clog configuration TOML file NOT in the current working directory
(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project
directory (i.e. /myproject/.clog.toml) you do not need to use both.
"#
    );
