                    args.git_dir = Some(PathBuf::from(&args_vec[i]));
                }
            }
            "-w" | "--work-tree" => {
                i += 1;
                if i < args_vec.len() {
                    args.work_tree = Some(PathBuf::from(&args_vec[i]));
                }
            }
            "-s" | "--subtitle" => {
                i += 1;
                if i < args_vec.len() {
                    args.subtitle = Some(args_vec[i].clone());
                }
            }
            "-o" | "--outfile" => {
                i += 1;
                if i < args_vec.len() {
                    args.outfile = Some(PathBuf::from(&args_vec[i]));
                }
            }
            "-c" | "--config" => {
                i += 1;
                if i < args_vec.len() {
                    args.config = Some(PathBuf::from(&args_vec[i]));
                }
            }
            "-i" | "--infile" => {
